  const find = (a) => { while (parent[a] !== a) { parent[a] = parent[parent[a]]; a = parent[a]; } return a; };
  for (let e = 0; e < ne; e++) { const r0 = find(elemNodes[8 * e]); for (let a = 1; a < 8; a++) { const r1 = find(elemNodes[8 * e + a]); if (r1 !== r0) parent[r1] = r0; } }
